/* Balochi Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Allah Bakhsh": "God-given — Persian khuda bakhsh", "Muhammad": "praised — Arabic", "Fatimah": "A beloved feminine name.", "Mir": "chief, leader — Arabic amir, as title", "Bibi": "lady — Persian", "Chakar": "The name of Chakar Rind, the great Baloch folk hero.", "Rind": "The tribe of the folk hero Chakar Rind; tribal names serve as surnames.", "Marri": "A major Baloch tribal name used as a surname.", "Bugti": "A major Baloch tribal name used as a surname.", "Mengal": "A major Baloch tribal name used as a surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Allah Bakhsh';
console.log(lookup(q));

